const WORD_INITIAL: React.CSSProperties = {
  opacity: 0,
  transform: "translateY(24px)",
  display: "inline-block",
}

function Word({ children, className }: { children: string; className?: string }) {
  return (
    <span style={WORD_INITIAL} className={`word${className ? ` ${className}` : ""}`}>
      {children}
    </span>
  )
}

export default function HeroContent() {
  const { titleRef, descRef, streamRef, brandsRef } = useHeroAnimation()

  return (
    <>
      <div className="grid gap-10 lg:grid-cols-2 lg:items-center lg:gap-16">

        <div className="flex flex-col gap-6">
          <h1
            ref={titleRef}
            className="text-4xl font-medium tracking-tight sm:text-5xl lg:text-6xl"
          >
            <Word>Every</Word>{" "}
            <Word>event,</Word>{" "}
            <Word className="italic font-normal">delivered</Word>{" "}
            <Word className="italic font-normal">instantly</Word>
          </h1>
          <p
            ref={descRef}
            style={{ opacity: 0 }}
            className="text-lg leading-relaxed font-light"
          >
            Connect your services with a reliable event pipeline. Orders, payments, and shipments stream in real time, exactly when you need them.
          </p>
          {/* Add CTA buttons here if needed */}
        </div>

        <div ref={streamRef} style={{ opacity: 0 }}>
          <EventStream />
        </div>

      </div>

      <section ref={brandsRef} style={{ opacity: 0 }}>
        <BrandsSectionV2 />
      </section>
    </>
  )
}

import { useEffect, useRef } from "react"
import gsap from "gsap"

export function useHeroAnimation() {
  const titleRef  = useRef<HTMLHeadingElement>(null)
  const descRef   = useRef<HTMLParagraphElement>(null)
  const streamRef = useRef<HTMLDivElement>(null)
  const brandsRef = useRef<HTMLElement>(null)

  useEffect(() => {
    const ctx = gsap.context(() => {
      const tl = gsap.timeline({ defaults: { ease: "power4.out" } })

      // Initial states are set in JSX — animate forward with to()
      tl.to(titleRef.current!.querySelectorAll(".word"), {
        opacity: 1,
        y: 0,
        duration: 0.8,
        stagger: 0.07,
      })

      .to(descRef.current, {
        opacity: 1,
        filter: "blur(0px)",
        y: 0,
        duration: 0.9,
        ease: "power3.out",
      }, "-=0.45")

      .to(streamRef.current, {
        opacity: 1,
        scale: 1,
        y: 0,
        rotationX: 0,
        transformPerspective: 1000,
        transformOrigin: "50% 0%",
        duration: 1.1,
        ease: "expo.out",
      }, "<0.1")

      .to(brandsRef.current, {
        opacity: 1,
        y: 0,
        duration: 0.6,
        ease: "power3.out",
      }, "-=0.5")
    })

    return () => ctx.revert()
  }, [])

  return { titleRef, descRef, streamRef, brandsRef }
}

