import type { Brand } from "../lib/brands"
import BrandLogo from "./brand-logo"

export default function Marquee({ brands }: { brands: Brand[] }) {
  return (
    <div className="bs2-marquee-wrap">
      <div className="bs2-fade bs2-fade-left" aria-hidden />
      <div className="bs2-fade bs2-fade-right" aria-hidden />

      <div className="bs2-track">
        <div className="bs2-set" role="list" aria-label="Brand logos">
          {brands.map((brand) => (
            <div key={brand.name} role="listitem" className="bs2-slot">
              <BrandLogo brand={brand} />
            </div>
          ))}
        </div>
        <div className="bs2-set" aria-hidden>
          {brands.map((brand) => (
            <div key={`dup-${brand.name}`} className="bs2-slot">
              <BrandLogo brand={brand} />
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

import type { Brand } from "../lib/brands"

export default function BrandLogo({ brand }: { brand: Brand }) {
  const Light = brand.light
  const Dark = brand.dark

  if (Dark) {
    return (
      <span className="inline-flex h-12 w-12 items-center justify-center">
        <Light className="bs2-logo block h-full w-full dark:hidden" aria-label={brand.name} />
        <Dark className="bs2-logo hidden h-full w-full dark:block" aria-label={brand.name} />
      </span>
    )
  }

  return (
    <span className="inline-flex h-12 w-12 items-center justify-center">
      <Light className="bs2-logo h-full w-full" aria-label={brand.name} />
    </span>
  )
}

// Sliding window buffer — no gap phase, transitions are frame-synchronous.
import { useLayoutEffect, useMemo, useReducer, useRef } from "react"

import { EVENTS, TYPE_CHAR_MS, TYPE_NEWLINE_MS, VISIBLE_EVENT_BUFFER } from "../lib/config"

type AnimationState = {
  buffer: string[]
  eventIdx: number
  charIdx: number
}

type AnimationAction = { type: "advanceChar" } | { type: "completeEvent" }

function animationReducer(state: AnimationState, action: AnimationAction): AnimationState {
  switch (action.type) {
    case "advanceChar":
      return { ...state, charIdx: state.charIdx + 1 }
    case "completeEvent": {
      const content = EVENTS[state.eventIdx]
      return {
        buffer: [...state.buffer, content].slice(-VISIBLE_EVENT_BUFFER),
        charIdx: 0,
        eventIdx: (state.eventIdx + 1) % EVENTS.length,
      }
    }
    default:
      return state
  }
}

function buildDisplayText(buffer: string[], eventIdx: number, charIdx: number): string {
  const wip = EVENTS[eventIdx].slice(0, charIdx)
  if (buffer.length === 0) return wip
  return buffer.join("\n\n") + "\n\n" + wip
}

export function useEventAnimation() {
  const [{ buffer, eventIdx, charIdx }, dispatch] = useReducer(animationReducer, {
    buffer: [],
    eventIdx: 0,
    charIdx: 0,
  })
  const scrollRef = useRef<HTMLDivElement>(null)

  const text = useMemo(
    () => buildDisplayText(buffer, eventIdx, charIdx),
    [buffer, eventIdx, charIdx],
  )

  useLayoutEffect(() => {
    const el = scrollRef.current
    if (!el) return
    el.scrollTop = Math.max(0, el.scrollHeight - el.clientHeight)
  }, [text])

  useLayoutEffect(() => {
    const content = EVENTS[eventIdx]

    if (charIdx >= content.length) {
      dispatch({ type: "completeEvent" })
      return
    }

    const ch = content[charIdx]
    const delay = ch === "\n" ? TYPE_NEWLINE_MS : TYPE_CHAR_MS
    const t = setTimeout(() => dispatch({ type: "advanceChar" }), delay)
    return () => clearTimeout(t)
  }, [charIdx, eventIdx])

  return { text, scrollRef }
}

export const TYPE_CHAR_MS = 16
export const TYPE_NEWLINE_MS = 38

/** Completed events kept in the sliding window; older ones drop off the top through the mask. */
export const VISIBLE_EVENT_BUFFER = 3

